import torch.nn as nn
import torch.nn.functional as F
import torch.distributed as dist
from typing import Optional


def _dist_initialized() -> bool:
    return dist.is_available() and dist.is_initialized()


def _get_world_size(group: Optional[dist.ProcessGroup] = None) -> int:
    if _dist_initialized():
        return dist.get_world_size(group)
    return 1


def _get_rank(group: Optional[dist.ProcessGroup] = None) -> int:
    if _dist_initialized():
        return dist.get_rank(group)
    return 0


def _split_along_dim(tensor: torch.Tensor, num_partitions: int, rank: int, dim: int) -> torch.Tensor:
    if num_partitions == 1:
        return tensor
    dim_size = tensor.size(dim)
    if dim_size % num_partitions != 0:
        raise ValueError(
            f"Dimension {dim} size {dim_size} not divisible by num_partitions {num_partitions}."
        )
    partition_size = dim_size // num_partitions
    start = rank * partition_size
    return tensor.narrow(dim, start, partition_size)


class _AllGather(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input: torch.Tensor, dim: int, group: Optional[dist.ProcessGroup]):
        world_size = _get_world_size(group)
        rank = _get_rank(group)
        ctx.dim = dim
        ctx.world_size = world_size
        ctx.rank = rank
        ctx.input_shape = input.shape
        if world_size == 1:
            return input
        input_contig = input.contiguous()
        tensor_list = [torch.empty_like(input_contig) for _ in range(world_size)]
        dist.all_gather(tensor_list, input_contig, group=group)
        output = torch.cat(tensor_list, dim=dim)
        return output

    @staticmethod
    def backward(ctx, grad_output: torch.Tensor):
        if ctx.world_size == 1:
            return grad_output, None, None
        dim = ctx.dim
        if dim < 0:
            dim = grad_output.dim() + dim
        input_size = ctx.input_shape[dim]
        start = ctx.rank * input_size
        grad_input = grad_output.narrow(dim, start, input_size).contiguous()
        return grad_input, None, None


class _AllReduce(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input: torch.Tensor, group: Optional[dist.ProcessGroup]):
        world_size = _get_world_size(group)
        ctx.world_size = world_size
        ctx.group = group
        if world_size == 1:
            return input
        output = input.clone()
        dist.all_reduce(output, group=group)
        return output

    @staticmethod
    def backward(ctx, grad_output: torch.Tensor):
        return grad_output, None


def _all_gather(tensor: torch.Tensor, dim: int = -1, group: Optional[dist.ProcessGroup] = None) -> torch.Tensor:
    return _AllGather.apply(tensor, dim, group)


def _all_reduce(tensor: torch.Tensor, group: Optional[dist.ProcessGroup] = None) -> torch.Tensor:
    return _AllReduce.apply(tensor, group)


class ColumnParallelLinear(nn.Module):
    def __init__(self, in_features: int, out_features: int, bias: bool, master_weight: torch.Tensor):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _get_world_size()
        self.rank = _get_rank()

        if out_features % self.world_size != 0:
            raise ValueError(
                f"out_features ({out_features}) must be divisible by world_size ({self.world_size})."
            )
        self.out_features_per_partition = out_features // self.world_size

        weight_partition = _split_along_dim(master_weight, self.world_size, self.rank, dim=0)
        self.weight = nn.Parameter(weight_partition.clone().detach())

        if bias:
            bias_size = self.out_features_per_partition
            bias_param = torch.zeros(
                bias_size,
                device=master_weight.device,
                dtype=master_weight.dtype,
            )
            self.bias = nn.Parameter(bias_param)
        else:
            self.register_parameter("bias", None)

    def forward(self, input: torch.Tensor) -> torch.Tensor:
        output_parallel = F.linear(input, self.weight, self.bias)
        if self.world_size > 1:
            output = _all_gather(output_parallel, dim=-1)
        else:
            output = output_parallel
        return output


class RowParallelLinear(nn.Module):
    def __init__(self, in_features: int, out_features: int, bias: bool, master_weight: torch.Tensor):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _get_world_size()
        self.rank = _get_rank()

        if in_features % self.world_size != 0:
            raise ValueError(
                f"in_features ({in_features}) must be divisible by world_size ({self.world_size})."
            )
        self.in_features_per_partition = in_features // self.world_size

        weight_partition = _split_along_dim(master_weight, self.world_size, self.rank, dim=1)
        self.weight = nn.Parameter(weight_partition.clone().detach())

        if bias:
            bias_param = torch.zeros(
                out_features,
                device=master_weight.device,
                dtype=master_weight.dtype,
            )
            self.bias = nn.Parameter(bias_param)
        else:
            self.register_parameter("bias", None)

    def forward(self, input: torch.Tensor) -> torch.Tensor:
        if self.world_size > 1:
            input_parallel = _split_along_dim(input, self.world_size, self.rank, dim=-1).contiguous()
        else:
            input_parallel = input
        output_parallel = F.linear(input_parallel, self.weight, bias=None)
        if self.world_size > 1:
            output = _all_reduce(output_parallel)
        else:
            output = output_parallel
        if self.bias is not None:
            output = output + self.bias
        return output
